import{_ as i,o as l,c as r,ag as n}from"./chunks/framework.DKalukzk.js";const m=JSON.parse('{"title":"Guide de préparation — Examen Excel","description":"","frontmatter":{"title":"Guide de préparation — Examen Excel","aside":false},"headers":[],"relativePath":"modules/02-excel/13-revision-examen.md","filePath":"modules/02-excel/13-revision-examen.md"}'),a={name:"modules/02-excel/13-revision-examen.md"};function t(s,e,o,u,d,c){return l(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="guide-de-preparation-—-examen-excel" tabindex="-1">Guide de préparation — Examen Excel <a class="header-anchor" href="#guide-de-preparation-—-examen-excel" aria-label="Permalink to &quot;Guide de préparation — Examen Excel&quot;">​</a></h1><h2 id="consignes-pendant-l-examen" tabindex="-1">Consignes pendant l’examen <a class="header-anchor" href="#consignes-pendant-l-examen" aria-label="Permalink to &quot;Consignes pendant l’examen&quot;">​</a></h2><ul><li>L’examen dure <strong>2 h 50</strong>.</li><li>Il comporte <strong>7 questions</strong>, chacune dans une <strong>feuille distincte</strong>.</li><li>Utilisez les <strong>onglets en bas</strong> ou le <strong>menu (…) / menu mobile</strong> pour naviguer.</li><li>Le fichier doit être <strong>remis sur Léa avant la fin de la période</strong>.</li><li>Aucune sortie de la classe n’est tolérée.</li><li>Travail <strong>individuel obligatoire</strong>.</li></ul><h3 id="ouvrages-permis" tabindex="-1">Ouvrages permis <a class="header-anchor" href="#ouvrages-permis" aria-label="Permalink to &quot;Ouvrages permis&quot;">​</a></h3><ul><li>Notes de cours disponibles sur le site du cours</li><li>Exercices réalisés en classe</li><li>Solutionnaires fournis</li></ul><h3 id="interdits" tabindex="-1">Interdits <a class="header-anchor" href="#interdits" aria-label="Permalink to &quot;Interdits&quot;">​</a></h3><ul><li>Tout outil d’intelligence artificielle</li><li>Tout moteur de recherche (Google, Bing, etc.)</li><li>Toute communication externe</li></ul><p><strong>Infraction : 0 à l’examen + déclaration de plagiat.</strong></p><hr><h2 id="structure-de-l-examen" tabindex="-1">Structure de l’examen <a class="header-anchor" href="#structure-de-l-examen" aria-label="Permalink to &quot;Structure de l’examen&quot;">​</a></h2><p>L’examen comporte <strong>7 questions</strong> :</p><ol><li><p><strong>Mise en forme</strong></p><ul><li>Ajustement des colonnes</li><li>Formats de cellule (date, $, %)</li><li>Bordures et présentation</li></ul></li><li><p><strong>Formules</strong></p><ul><li>Calculs arithmétiques</li><li>Références relatives et absolues</li><li>SOMME, MOYENNE, NBVAL</li></ul></li><li><p><strong>Fonctions de date</strong></p><ul><li>AUJOURDHUI</li><li>DATE</li><li>ANNEE, MOIS, JOUR</li><li>FIN.MOIS</li><li>Calcul de délais</li></ul></li><li><p><strong>Fonctions conditionnelles</strong></p><ul><li>SI</li><li>SI avec ET</li><li>SOMME.SI / MOYENNE.SI</li><li>SIERREUR</li></ul></li><li><p><strong>Mise en forme conditionnelle</strong></p><ul><li>Règle basée sur un nombre</li><li>Règle basée sur du texte</li></ul></li><li><p><strong>RECHERCHEV</strong></p><ul><li>Utilisation correcte des paramètres</li><li>Référence absolue de la table</li><li>Correspondance exacte (FAUX)</li></ul></li><li><p><strong>Tableau croisé dynamique + graphique</strong></p><ul><li>1 champ en Lignes</li><li>1 champ en Colonnes</li><li>1 champ en Valeurs (Somme)</li><li>Création d’un graphique</li></ul></li></ol><hr><h2 id="comment-bien-se-preparer" tabindex="-1">Comment bien se préparer <a class="header-anchor" href="#comment-bien-se-preparer" aria-label="Permalink to &quot;Comment bien se préparer&quot;">​</a></h2><p>Pour bien réussir :</p><ul><li>Refaire les <strong>exercices vus en classe</strong>.</li><li>Revoir les <strong>solutionnaires</strong> et comprendre les étapes.</li><li>S’assurer de comprendre : <ul><li>La différence entre <strong>référence relative et absolue</strong></li><li>Les <strong>paramètres attendus</strong> par chaque fonction</li><li>La logique derrière les fonctions conditionnelles</li><li>Le fonctionnement d’un TCD (Lignes / Colonnes / Valeurs)</li></ul></li></ul><p>L’objectif n’est pas de mémoriser des formules, mais de <strong>comprendre leur structure et leur logique</strong>.</p><hr><p>Bonne préparation.</p>',19)])])}const g=i(a,[["render",t]]);export{m as __pageData,g as default};
